text:
{
 "reason": {
  "es": "衆議院《しゅうぎいん》の委員長《いいんちょう》の説明《せつめい》では、この協定《きょうてい》は投資《とうし》のきまりを決《き》めるものです。投資《とうし》をふやして、日本《にほん》と相手《あいて》の国《くに》の経済《けいざい》のつながりを強《つよ》くするためです。",
  "hs": "衆議院の外務委員長の報告では、この協定は、投資についての法的なしくみを定めるものだと説明された。内国民待遇《ないこくみんたいぐう》や最恵国待遇《さいけいこくたいぐう》などを定め、投資を広げて日本と相手の国の経済の結びつきを強めるためだという。",
  "std": "衆議院外務委員長の報告によると、協定は、日本と相手国の間で投資の拡大により経済関係を一層強化するため、内国民待遇や最恵国待遇の供与など、投資に関する法的枠組みを定めるものとされている。",
  "univ": "衆議院外務委員長の報告では、本協定は、我が国と相手国との間で、投資の拡大により経済関係を一層強化するため、投資財産に対する内国民待遇及び最恵国待遇の供与等投資に関する法的枠組みについて定めるものとされている。"
 },
 "who": {
  "es": "日本《にほん》とアラブ首長国連邦《しゅちょうこくれんぽう》の国《くに》と、相手《あいて》の国《くに》に投資《とうし》をする人《ひと》や会社《かいしゃ》に関係《かんけい》します。",
  "hs": "日本とアラブ首長国連邦《しゅちょうこくれんぽう》の両国と、相手の国で投資をする両国の投資家（人や会社）と、その投資財産。",
  "std": "日本とアラブ首長国連邦の両国（締約国）と、相手国で投資をする両国の投資家とその投資財産。",
  "univ": "日本国及びアラブ首長国連邦の両締約国並びに他方の締約国の区域における一方の締約国の投資家及びその投資財産。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》では、4月《がつ》2日《ふつか》に、この協定《きょうてい》など5件《けん》を外務委員会《がいむいいんかい》が任《まか》されました。3日《みっか》に茂木《もてぎ》外務大臣《がいむだいじん》が説明《せつめい》し、10日《とおか》に質問《しつもん》をしました。話《はな》し合《あ》いのあと、5件《けん》とも賛成《さんせい》が多《おお》く、認《みと》めるべきだと決《き》めました。参議院《さんぎいん》では、外交防衛委員会《がいこうぼうえいいいんかい》が5件《けん》をまとめて調《しら》べました。質問《しつもん》では、次《つぎ》のことなどが取《と》り上《あ》げられました。アラブ首長国連邦《しゅちょうこくれんぽう》などとの協定《きょうてい》が「保護型《ほごがた》」になったわけ。アラブ首長国連邦《しゅちょうこくれんぽう》との協定《きょうてい》での、天然資源《てんねんしげん》（自然《しぜん》から取《と》れるもの）のあつかい。日本《にほん》が結《むす》んだ投資《とうし》の協定《きょうてい》の数《かず》などと、これからの話《はな》し合《あ》いの進《すす》め方《かた》。日本共産党《にほんきょうさんとう》の井上《いのうえ》理事《りじ》が反対《はんたい》の意見《いけん》を言《い》いました。決《き》めた結果《けっか》、5件《けん》とも多《おお》くの賛成《さんせい》で、認《みと》めるべきだとなりました。※正確《せいかく》には「アラブ首長国連邦《しゅちょうこくれんぽう》、ヨルダン及《およ》びモロッコとの投資協定《とうしきょうてい》が保護型《ほごがた》となった理由《りゆう》」などです。",
  "hs": "衆議院では、4月2日にこの協定など5件が外務委員会に付託《ふたく》された（任された）。3日に茂木《もてぎ》外務大臣が提案の理由を説明し、10日に質疑をした。討論のあと順に採決し、5件はいずれも賛成多数で承認すべきだと決めた。参議院では、外交防衛委員会が5件をまとめて審議《しんぎ》した。質疑では、アラブ首長国連邦《しゅちょうこくれんぽう》・ヨルダン・モロッコとの協定が「保護型」になった理由が取り上げられた。また、アラブ首長国連邦《しゅちょうこくれんぽう》との協定での天然資源のあつかいや、日本の投資協定の締結《ていけつ》状況《じょうきょう》と今後の交渉《こうしょう》方針なども取り上げられた。討論では日本共産党の井上理事が反対の意見を述べ、採決の結果、5件はいずれも多数で承認すべきだと決めた。",
  "std": "衆議院では、4月2日に外務委員会に付託され、3日に茂木外務大臣が提案理由を説明し、10日に質疑を行った。討論の後、順次採決し、5件はいずれも賛成多数で承認すべきものと議決した。参議院の外交防衛委員会では、5件を一括して審査し、アラブ首長国連邦、ヨルダン、モロッコとの投資協定が保護型となった理由、アラブ首長国連邦との協定における天然資源の扱い、日本の投資協定の締結状況と今後の交渉方針などについて質疑が行われた。討論では日本共産党の井上理事が5件に反対する意見を述べ、採決の結果、5件はいずれも多数で承認すべきものと決定した。",
  "univ": "衆議院では、本件を含む5件が去る2日外務委員会に付託され、翌3日茂木外務大臣から提案理由の説明を聴取し、10日に質疑を行い、討論の後、順次採決を行った結果、5件はいずれも賛成多数をもって承認すべきものと議決した。参議院では、外交防衛委員会において5件を一括して議題とし、アラブ首長国連邦、ヨルダン及びモロッコとの投資協定が保護型となった理由、アラブ首長国連邦との協定における天然資源の扱い、我が国の投資協定の締結状況と今後の交渉方針等について質疑が行われた。討論では、日本共産党の井上理事より5件に反対する旨の意見が述べられ、順次採決の結果、5件はいずれも多数をもって承認すべきものと決定した。"
 },
 "views": [
  {
   "side": "反対",
   "group": "日本共産党",
   "where": "衆議院 外務委員会、参議院 外交防衛委員会",
   "text": {
    "es": "日本共産党《にほんきょうさんとう》は、反対《はんたい》しました。大《おお》きな会社《かいしゃ》の得《とく》を先《さき》にする、国《くに》の計画《けいかく》の一部《いちぶ》だと言《い》いました。いくつもの国《くに》で仕事《しごと》をする日本《にほん》の会社《かいしゃ》が、外国《がいこく》へ出《で》ていくのを進《すす》めるもの、とも言《い》いました。アラブ首長国連邦《しゅちょうこくれんぽう》との協定《きょうてい》についても言《い》いました。日本経団連《にほんけいだんれん》などが早《はや》く結《むす》ぶよう求《もと》めていたものだ、という意見《いけん》です。",
    "hs": "日本共産党は、投資の協定は大企業《だいきぎょう》の利益を優先する成長戦略の一部だと述べた。日本の多国籍《たこくせき》企業《きぎょう》（いくつもの国で事業をする会社）の海外展開を進めるためのものだとも述べた。また、アラブ首長国連邦《しゅちょうこくれんぽう》との協定は、日本経団連などの早く結んでほしいという要望にこたえたものだとして、反対した。",
    "std": "日本共産党は、投資関連協定は大企業の利益を優先する成長戦略の一環で、日本の多国籍企業の海外展開を促進するためのものだと述べた。また、アラブ首長国連邦との協定は日本経団連などからの早期締結の要望に応えたものだとして、反対した。",
    "univ": "日本共産党は、投資関連協定は大企業の利益優先の成長戦略の一環であり、日本の多国籍企業の海外展開を促進するためのものであること、とりわけアラブ首長国連邦との協定は日本経団連などからの早期締結の要望に応えたものであることを挙げ、反対した。"
   }
  }
 ],
 "no_debate": false
}
